import { styled } from '@hexa-ui/theme';

import { DDT_COLORS } from '../../DrillDownTable.styles';

export const DDTToolbar = styled('div', {
  display: 'flex',
  alignItems: 'center',
  justifyContent: 'space-between',
  padding: '16px 16px 0 16px',
  minHeight: '56px',
  boxSizing: 'border-box',
});

export const DDTToolbarLeft = styled('div', {
  display: 'flex',
  alignItems: 'baseline',
  gap: '6px',
});

export const DDTTitle = styled('span', {
  fontFamily: "'Barlow', sans-serif",
  fontWeight: 600,
  fontSize: '20px',
  lineHeight: '24px',
  color: DDT_COLORS.text.primary,
});

export const DDTUnit = styled('span', {
  fontFamily: "'Work Sans', sans-serif",
  fontWeight: 400,
  fontSize: '14px',
  lineHeight: '16px',
  color: DDT_COLORS.text.secondary,
});

export const DDTToggleRow = styled('div', {
  display: 'flex',
  alignItems: 'center',
  gap: '8px',
});

export const DDTToggleLabel = styled('span', {
  fontFamily: "'Work Sans', sans-serif",
  fontWeight: 400,
  fontSize: '14px',
  color: DDT_COLORS.text.primary,
});
